# Robust pagination with retry
def fetch_all_with_retry(fetch_page, access_token, max_retries=3):
    all_items = []
    page_index = 0
    while True:
        for attempt in range(max_retries):
            try:
                page = fetch_page(access_token=access_token, page_index=page_index)
                break
            except Exception:
                if attempt == max_retries - 1:
                    raise
        if not page:
            break
        all_items.extend(page)
        page_index += 1
    return all_items

